import pytest

from youtube_dl.compat import compat_urllib_error
from youtube_dl.downloader.dash import DashSegmentsFD
from youtube_dl.utils import DownloadError


class _FakeDashSegmentsFD:
    def __init__(self, params=None, resume_index=0, download_actions=None):
        self.params = params or {}
        self.resume_index = resume_index
        self.download_actions = list(download_actions or [])
        self.prepared_contexts = []
        self.download_calls = []
        self.appended_fragments = []
        self.retry_reports = []
        self.skipped_fragments = []
        self.error_reports = []
        self.finished_contexts = []

    def _prepare_and_start_frag_download(self, ctx):
        self.prepared_contexts.append(dict(ctx))
        ctx["fragment_index"] = self.resume_index

    def _download_fragment(self, ctx, fragment_url, info_dict):
        self.download_calls.append((fragment_url, info_dict))
        action = self.download_actions.pop(0)
        if isinstance(action, BaseException):
            raise action
        return action

    def _append_fragment(self, ctx, fragment_content):
        self.appended_fragments.append(fragment_content)

    def report_retry_fragment(self, error, frag_index, count, fragment_retries):
        self.retry_reports.append(
            (error, frag_index, count, fragment_retries)
        )

    def report_skip_fragment(self, frag_index):
        self.skipped_fragments.append(frag_index)

    def report_error(self, message):
        self.error_reports.append(message)

    def _finish_frag_download(self, ctx):
        self.finished_contexts.append(dict(ctx))


def _http_error(url="https://cdn.example/segment.m4s"):
    return compat_urllib_error.HTTPError(
        url, 404, "missing fragment", {}, None
    )


def test_real_download_uses_test_fragment_and_resolves_relative_url():
    info_dict = {
        "fragment_base_url": "https://cdn.example/video/",
